inputs = ['fhfzc', 'hagi', 'kycjwv', 'daaafv', 'bziug']
outputs = ['fhfcwvc', 'hagi', 'kycuwv', 'daaafv', 'aiabccwviug']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"\nExample {i}:")
        print(f"  Input:  '{inp}'")
        print(f"  Output: '{out}'")

        # Find differences character by character
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"    Position {j}: '{inp[j]}' -> '{out[j]}'")

        if len(inp) != len(out):
            if len(inp) > len(out):
                print(f"    Extra chars in input: '{inp[len(out):]}'")
            else:
                print(f"    Extra chars in output: '{out[len(inp):]}'")

